{
  "name": "@joe-broadhead/opencode-messaging",
  "version": "0.9.2",
  "description": "OpenCode plugin for Messaging agent-to-agent messaging and tasks",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/joe-broadhead/opencode-messaging.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=22.15.0"
  },
  "author": "Joe Broadhead",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "a2a",
    "agent-to-agent",
    "messaging"
  ],
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./rpc": "./dist/rpc.js",
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist/index.js",
    "dist/rpc.js",
    "dist/tui.js",
    "dist/third-party-notices.md",
    "skills/opencode-messaging/SKILL.md",
    "assets/icon.svg",
    "views/section.html",
    "docs/*.md",
    "README.md",
    "LICENSE",
    "NOTICE",
    "CHANGELOG.md"
  ],
  "scripts": {
    "gates": "node scripts/gates.mjs",
    "compile": "tsc -b tsconfig.json tsconfig.tui.json && node scripts/build-tui.mjs && node scripts/bundle.mjs",
    "clean": "node scripts/clean.mjs",
    "test": "vitest run",
    "typecheck": "tsc -p tsconfig.test.json",
    "test:host": "node node_modules/vitest/vitest.mjs run --config test/host/vitest.config.ts",
    "golden:update": "MESSAGING_GOLDEN=update vitest run test/golden.test.ts",
    "check:package": "node scripts/check-package.mjs",
    "check:library": "node scripts/check-library.mjs",
    "test:pack": "node --test scripts/pack-checks.test.mjs",
    "check:platforms": "node scripts/check-platforms.mjs",
    "pack:tarball": "node scripts/pack-tarballs.mjs",
    "smoke:pack": "node scripts/smoke-pack.mjs",
    "audit:shipped": "node scripts/audit-shipped.mjs",
    "messaging:bump": "node scripts/messaging-bump.mjs",
    "jelly:update": "node scripts/jelly-declaration.mjs"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.5 <2.3",
    "@opentui/solid": ">=0.8.0 <0.9",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@babel/core": "7.29.7",
    "@babel/preset-typescript": "7.27.1",
    "@joe-broadhead/messaging": "0.9.2",
    "@opencode/plugin": "2.2.5",
    "@opentui/solid": "0.8.0",
    "@types/node": "22.20.5",
    "babel-preset-solid": "1.9.16",
    "rolldown": "1.2.16",
    "solid-js": "1.9.17",
    "typescript": "5.9.3",
    "uqr": "0.1.3",
    "vitest": "5.0.5",
    "zod": "4.6.7"
  },
  "optionalDependencies": {
    "@joe-broadhead/messaging-bin-darwin-arm64": "0.9.2",
    "@joe-broadhead/messaging-bin-darwin-x64": "0.9.2",
    "@joe-broadhead/messaging-bin-linux-arm64-gnu": "0.9.2",
    "@joe-broadhead/messaging-bin-linux-x64-gnu": "0.9.2",
    "@joe-broadhead/messaging-bin-win32-x64": "0.9.2"
  },
  "jelly": {
    "title": "Messaging",
    "summary": "Your teammates, their coding agents and the people you message.",
    "icon": "assets/icon.svg",
    "tools": [
      {
        "name": "messaging.contacts",
        "permission": "messaging.read",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "messaging.conversations",
        "permission": "messaging.read",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "messaging.send",
        "permission": "messaging.send",
        "effect": "allow",
        "readOnly": false
      },
      {
        "name": "messaging.inbox",
        "permission": "messaging.read",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "messaging.read",
        "permission": "messaging.read",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "messaging.search",
        "permission": "messaging.read",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "messaging.context",
        "permission": "messaging.read",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "messaging.tasks",
        "permission": "messaging.read",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "messaging.task_update",
        "permission": "messaging.send",
        "effect": "allow",
        "readOnly": false
      },
      {
        "name": "messaging.task_cancel",
        "permission": "messaging.send",
        "effect": "allow",
        "readOnly": false
      }
    ],
    "skills": [
      "opencode-messaging"
    ],
    "instructions": "docs/agent-instructions.md",
    "rpc": [
      {
        "name": "people.search",
        "label": "find people",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "type": "object",
          "properties": {
            "query": {
              "type": "string",
              "maxLength": 100
            },
            "limit": {
              "type": "integer",
              "minimum": 1,
              "maximum": 200
            }
          },
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "people.get",
        "label": "read a person's page",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "type": "object",
          "properties": {
            "people": {
              "minItems": 1,
              "maxItems": 100,
              "type": "array",
              "items": {
                "anyOf": [
                  {
                    "type": "string",
                    "pattern": "^[a-z][a-z0-9-]{0,31}$"
                  },
                  {
                    "type": "string",
                    "pattern": "^p_[a-z2-7]{26}$"
                  }
                ]
              }
            }
          },
          "required": [
            "people"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "grant.list",
        "label": "read what people and their agents may do",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "type": "object",
          "properties": {
            "subject": {
              "anyOf": [
                {
                  "type": "object",
                  "properties": {
                    "person": {
                      "anyOf": [
                        {
                          "type": "string",
                          "pattern": "^[a-z][a-z0-9-]{0,31}$"
                        },
                        {
                          "type": "string",
                          "pattern": "^p_[a-z2-7]{26}$"
                        }
                      ]
                    }
                  },
                  "required": [
                    "person"
                  ],
                  "additionalProperties": false
                },
                {
                  "type": "object",
                  "properties": {
                    "conv": {
                      "type": "string",
                      "pattern": "^(?:[ds]_[a-z2-7]{26}|c_[0-7][0-9A-HJKMNP-TV-Z]{25})$"
                    }
                  },
                  "required": [
                    "conv"
                  ],
                  "additionalProperties": false
                }
              ]
            }
          },
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "conv.list",
        "label": "list your conversations",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "type": "object",
          "properties": {
            "key": {
              "type": "string",
              "minLength": 1,
              "maxLength": 200
            },
            "filter": {
              "type": "object",
              "properties": {
                "unread": {
                  "type": "boolean"
                },
                "mentions": {
                  "type": "boolean"
                },
                "kind": {
                  "type": "string",
                  "enum": [
                    "dm",
                    "group",
                    "channel",
                    "self"
                  ]
                },
                "archived": {
                  "type": "boolean"
                }
              },
              "additionalProperties": false
            },
            "limit": {
              "type": "integer",
              "minimum": 1,
              "maximum": 50
            },
            "cursor": {
              "type": "string",
              "minLength": 1,
              "maxLength": 512
            }
          },
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "conv.get",
        "label": "read a conversation's details",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "type": "object",
          "properties": {
            "key": {
              "type": "string",
              "minLength": 1,
              "maxLength": 200
            },
            "cid": {
              "type": "string",
              "pattern": "^(?:[ds]_[a-z2-7]{26}|c_[0-7][0-9A-HJKMNP-TV-Z]{25})$"
            }
          },
          "required": [
            "cid"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "conv.read",
        "label": "read a conversation",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "type": "object",
          "properties": {
            "key": {
              "type": "string",
              "minLength": 1,
              "maxLength": 200
            },
            "cid": {
              "type": "string",
              "pattern": "^(?:[ds]_[a-z2-7]{26}|c_[0-7][0-9A-HJKMNP-TV-Z]{25})$"
            },
            "thread": {
              "type": "string",
              "pattern": "^[0-7][0-9A-HJKMNP-TV-Z]{25}$"
            },
            "before": {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            "after": {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            "around": {
              "type": "string",
              "pattern": "^[0-7][0-9A-HJKMNP-TV-Z]{25}$"
            },
            "limit": {
              "type": "integer",
              "minimum": 1,
              "maximum": 50
            },
            "cursor": {
              "type": "string",
              "minLength": 1,
              "maxLength": 512
            }
          },
          "required": [
            "cid"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "conv.members",
        "label": "list a conversation's members",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "type": "object",
          "properties": {
            "cid": {
              "type": "string",
              "pattern": "^(?:[ds]_[a-z2-7]{26}|c_[0-7][0-9A-HJKMNP-TV-Z]{25})$"
            },
            "limit": {
              "type": "integer",
              "minimum": 1,
              "maximum": 50
            },
            "cursor": {
              "type": "string",
              "minLength": 1,
              "maxLength": 512
            }
          },
          "required": [
            "cid"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "conv.threads",
        "label": "list a conversation's threads",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "type": "object",
          "properties": {
            "cid": {
              "type": "string",
              "pattern": "^(?:[ds]_[a-z2-7]{26}|c_[0-7][0-9A-HJKMNP-TV-Z]{25})$"
            },
            "filter": {
              "type": "string",
              "enum": [
                "all",
                "unread",
                "following"
              ]
            },
            "limit": {
              "type": "integer",
              "minimum": 1,
              "maximum": 50
            },
            "cursor": {
              "type": "string",
              "minLength": 1,
              "maxLength": 512
            }
          },
          "required": [
            "cid"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "conv.search",
        "label": "search your conversations",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "type": "object",
          "properties": {
            "key": {
              "type": "string",
              "minLength": 1,
              "maxLength": 200
            },
            "query": {
              "type": "string",
              "minLength": 1,
              "maxLength": 200
            },
            "cid": {
              "type": "string",
              "pattern": "^(?:[ds]_[a-z2-7]{26}|c_[0-7][0-9A-HJKMNP-TV-Z]{25})$"
            },
            "from": {
              "type": "string",
              "pattern": "^(?:[a-z][a-z0-9-]{0,31}|p_[a-z2-7]{26})(?:\\/[a-z0-9][a-z0-9._-]{0,63})?$"
            },
            "after": {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            "before": {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            "thread": {
              "type": "string",
              "pattern": "^[0-7][0-9A-HJKMNP-TV-Z]{25}$"
            },
            "has": {
              "type": "string",
              "enum": [
                "file",
                "link"
              ]
            },
            "limit": {
              "type": "integer",
              "minimum": 1,
              "maximum": 50
            },
            "cursor": {
              "type": "string",
              "minLength": 1,
              "maxLength": 512
            }
          },
          "required": [
            "query"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "conv.sync",
        "label": "follow your conversations as they change",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "type": "object",
          "properties": {
            "key": {
              "type": "string",
              "minLength": 1,
              "maxLength": 200
            },
            "after": {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            "waitMs": {
              "type": "integer",
              "minimum": 0,
              "maximum": 25000
            },
            "limit": {
              "type": "integer",
              "minimum": 1,
              "maximum": 50
            }
          },
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "request.list",
        "label": "read the requests waiting for you",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "type": "object",
          "properties": {},
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "request.waiting",
        "label": "read what waits on others",
        "permission": "messaging.read",
        "readOnly": true,
        "input": {
          "ty
…[文件过长——仅保留首 16KB 与末 8KB]…
equired": [
            "link",
            "sas"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "device.remove",
        "label": "remove one of your devices",
        "target": "service",
        "class": "local",
        "confirm": "always",
        "preview": "device.remove.preview",
        "summary": [
          "reason"
        ],
        "views": [
          "messaging"
        ],
        "input": {
          "type": "object",
          "properties": {
            "device": {
              "type": "string",
              "pattern": "^[A-Za-z0-9_-]{43}$",
              "description": "Ed25519 public key of a machine, base64url"
            },
            "reason": {
              "type": "string",
              "enum": [
                "self",
                "removed",
                "lost"
              ]
            },
            "token": {
              "type": "string",
              "maxLength": 8192,
              "pattern": "^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$"
            }
          },
          "required": [
            "device"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "settings.set",
        "label": "change this device's Messaging settings",
        "target": "service",
        "class": "local",
        "confirm": "always",
        "preview": "settings.set.preview",
        "summary": [
          "changes"
        ],
        "views": [
          "messaging"
        ],
        "input": {
          "type": "object",
          "properties": {
            "revision": {
              "type": "string",
              "minLength": 1,
              "maxLength": 64
            },
            "changes": {
              "type": "object",
              "properties": {
                "outbound.refuseSecrets": {
                  "type": "string",
                  "enum": [
                    "on",
                    "off"
                  ]
                }
              },
              "additionalProperties": false
            }
          },
          "required": [
            "revision",
            "changes"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "task.cancel",
        "label": "stop a task your agent asked of another agent",
        "target": "service",
        "class": "local",
        "confirm": "always",
        "summary": [
          "reason"
        ],
        "views": [
          "messaging"
        ],
        "input": {
          "type": "object",
          "properties": {
            "taskId": {
              "type": "string",
              "pattern": "^[0-7][0-9A-HJKMNP-TV-Z]{25}$"
            },
            "reason": {
              "type": "string",
              "maxLength": 1000
            },
            "token": {
              "type": "string",
              "pattern": "^[A-Za-z0-9_-]{43}$"
            }
          },
          "required": [
            "taskId",
            "token"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "task.stop",
        "label": "stop a task your agent is doing for another agent",
        "target": "service",
        "class": "local",
        "confirm": "always",
        "summary": [
          "taskId"
        ],
        "views": [
          "messaging"
        ],
        "input": {
          "type": "object",
          "properties": {
            "taskId": {
              "type": "string",
              "pattern": "^[0-7][0-9A-HJKMNP-TV-Z]{25}$"
            },
            "token": {
              "type": "string",
              "pattern": "^[A-Za-z0-9_-]{43}$"
            }
          },
          "required": [
            "taskId",
            "token"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "turn.cancel",
        "label": "stop your agent's running turn",
        "target": "service",
        "class": "local",
        "confirm": "always",
        "summary": [
          "session"
        ],
        "views": [
          "messaging"
        ],
        "input": {
          "type": "object",
          "properties": {
            "device": {
              "type": "string",
              "pattern": "^[A-Za-z0-9_-]{43}$",
              "description": "Ed25519 public key of a machine, base64url"
            },
            "session": {
              "type": "string",
              "pattern": "^[a-z0-9][a-z0-9._-]{0,63}$"
            },
            "turn": {
              "type": "string",
              "pattern": "^[0-7][0-9A-HJKMNP-TV-Z]{25}$"
            }
          },
          "required": [
            "device",
            "session"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      },
      {
        "name": "reach.set",
        "label": "change who can reach you and how agents may ask yours",
        "target": "service",
        "class": "local",
        "confirm": "always",
        "preview": "reach.set.preview",
        "summary": [
          "changes"
        ],
        "views": [
          "messaging"
        ],
        "input": {
          "type": "object",
          "properties": {
            "revision": {
              "type": "string",
              "minLength": 1,
              "maxLength": 64
            },
            "changes": {
              "type": "object",
              "properties": {
                "message": {
                  "type": "string",
                  "enum": [
                    "open",
                    "ask",
                    "never"
                  ]
                },
                "ask": {
                  "type": "string",
                  "enum": [
                    "open",
                    "ask",
                    "never"
                  ]
                }
              },
              "additionalProperties": false
            }
          },
          "required": [
            "revision",
            "changes"
          ],
          "additionalProperties": false
        },
        "output": {
          "type": "object"
        }
      }
    ],
    "asks": [
      "messaging.send"
    ],
    "resources": [
      "messaging"
    ],
    "service": {
      "id": "messaging",
      "label": "Messaging service",
      "sockets": [
        "agent.sock",
        "admin.sock"
      ],
      "health": "agent.sock",
      "agent": "agent.sock",
      "admin": "admin.sock",
      "wakes": true,
      "backup": {
        "exclude": [
          "identity.json",
          "pairing.json"
        ]
      }
    },
    "section": {
      "id": "messaging",
      "title": "Messaging",
      "page": "views/section.html",
      "rpc": [
        "people.search",
        "people.get",
        "grant.list",
        "conv.list",
        "conv.get",
        "conv.read",
        "conv.members",
        "conv.threads",
        "conv.search",
        "conv.sync",
        "request.list",
        "request.waiting",
        "sessions.list",
        "tasks.list",
        "tasks.get",
        "device.status",
        "device.list",
        "notice.list",
        "conv.outbox",
        "settings.get",
        "reach.get"
      ]
    },
    "notices": [
      {
        "id": "message",
        "label": "Message",
        "category": "message",
        "preview": "name"
      },
      {
        "id": "request",
        "label": "Request",
        "category": "request",
        "preview": "name"
      },
      {
        "id": "alert",
        "label": "Messaging alert",
        "category": "alert",
        "preview": "line"
      }
    ],
    "turns": {
      "label": "Messages"
    },
    "requires": [
      "service",
      "section",
      "actions",
